  1	/* Wishweave Wonders — shared namespace, tuning values and small utilities.
  2	   Loaded first. Every game script attaches to globalThis.WW so the same files
  3	   run in the browser, the Android WebView and Node unit tests. */
  4	(function (WW) {
  5	  'use strict';
  6	
  7	  WW.VERSION = '1.0.0';
  8	  WW.DESIGN = { w: 841, h: 1870 };
  9	  WW.PLATES = WW.PLATES || {};
 10	
 11	  /* Gameplay timing in seconds and speeds in metres/second. The values marked
 12	     "spec" come from docs/LEVEL1-GAMEPLAY-SPEC.md; the rest are tuning targets
 13	     checked by tests/unit and tests/e2e. */
 14	  WW.TUNING = {
 15	    countdown: 3,
 16	    purlSpeed: 5.0,
 17	    purlAccel: 9,                 // m/s² when starting/stopping
 18	    laneChangeTime: 0.22,
 19	    jumpTime: 0.68,
 20	    jumpAirborneAbove: 0.3,       // jump height fraction that clears Snagling's contact
 21	    inputBufferTime: 0.15,        // swipe-up within this time before landing is replayed
 22	
 23	    snagRevealToContact: 0.55,    // spec: visible reveal to possible contact
 24	    snagContactWindow: 0.10,      // contact is tested for this long after the hop lands
 25	    snagTangle: 0.5,              // spec: ankle tangle duration
 26	    hitImmunity: 1.6,             // spec: post-hit damage immunity
 27	    slowAfterHit: 0.6,            // speed multiplier while recovering footing
 28	    slowAfterHitTime: 1.2,
 29	    snagRetreat: 1.4,
 30	    dropAheadF: 0.10,             // dropped thread lands this far ahead (path fraction)
 31	    dropSpacingF: 0.07,
 32	    recoveryLoopTime: 2.6,        // local loop that returns Purl to the landing entry
 33	    failDelay: 1.2,
 34	
 35	    ribbonUnfurl: 1.3,
 36	    shortcutUnroll: 1.5,
 37	    tasselLift: 0.45,
 38	    tasselStagger: 0.3,
 39	    butterflyEmerge: 0.7,
 40	    butterflyFly: 1.7,
 41	    butterflyPlace: 0.45,
 42	    routeSettle: 0.25,            // pause after an opening completes before Purl moves
 43	
 44	    pickupRadiusF: 0.035,         // path-fraction tolerance for collecting a thread
 45	    dropPickupLane: 0.6,          // |lane - dropLane| must be below this to recover a drop
 46	    cueRepeatAfter: 4,
 47	
 48	    loopSpeed: 5.0,
 49	    loopSpeedJitter: 0.04,
 50	    loopReact: [0.45, 1.3],
 51	    loopHesitateChance: 0.22,
 52	    loopHesitate: [0.5, 1.2],
 53	    loopHopMissChance: 0.3,
 54	    loopStumble: 0.9,
 55	    loopDropOnStumbleChance: 0.35,
 56	    loopRecover: 1.4,
 57	
 58	    finishWaitForLoop: 25
 59	  };
 60	
 61	  /* Deterministic PRNG (mulberry32). Only the race simulation consumes it. */
 62	  WW.rng = function (seed) {
 63	    let a = (seed >>> 0) || 1;
 64	    const next = function () {
 65	      a = (a + 0x6D2B79F5) >>> 0;
 66	      let t = a;
 67	      t = Math.imul(t ^ (t >>> 15), t | 1);
 68	      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
 69	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
 70	    };
 71	    return {
 72	      next: next,
 73	      range: function (lo, hi) { return lo + (hi - lo) * next(); },
 74	      chance: function (p) { return next() < p; },
 75	      pick: function (list) { return list[Math.floor(next() * list.length)]; }
 76	    };
 77	  };
 78	
 79	  WW.util = {
 80	    clamp: function (v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; },
 81	    lerp: function (a, b, t) { return a + (b - a) * t; },
 82	    smooth: function (t) { t = t < 0 ? 0 : t > 1 ? 1 : t; return t * t * (3 - 2 * t); },
 83	    easeOutBack: function (t) { const c = 1.70158; t -= 1; return 1 + (c + 1) * t * t * t + c * t * t; },
 84	    approach: function (value, target, maxDelta) {
 85	      return value < target ? Math.min(value + maxDelta, target) : Math.max(value - maxDelta, target);
 86	    },
 87	    /* Critically damped follow, frame-rate independent. */
 88	    damp: function (value, target, halfLife, dt) {
 89	      return target + (value - target) * Math.pow(2, -dt / Math.max(halfLife, 1e-4));
 90	    }
 91	  };
 92	})(globalThis.WW = globalThis.WW || {});
 93	/* Route geometry shared by the simulation, renderer and authoring tools.
 94	
 95	   A path is an array of control points [x, y, w, lane] in plate design pixels
 96	   (841 × 1870):
 97	     x, y  foot point of the lane centre (bottom-centre sprite anchor)
 98	     w     the racer's on-screen sprite width at that point (depth scale)
 99	     lane  horizontal distance in plate pixels between adjacent lanes (0 = single file)
100	
101	   Positions are smoothed with a Catmull-Rom spline. The path parameter f (0..1)
102	   is proportional to distance measured in racer widths (∫ |dp| / w), so a racer
103	   moving at a constant world speed covers equal f per second whether the path is
104	   near the camera or far away. Fractions in plate data always use this metric. */
105	(function (WW) {
106	  'use strict';
107	  const SUB = 12;
108	  const cache = new WeakMap();
109	
110	  function catmull(p0, p1, p2, p3, t) {
111	    const t2 = t * t, t3 = t2 * t;
112	    return 0.5 * ((2 * p1) + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 + (-p0 + 3 * p1 - 3 * p2 + p3) * t3);
113	  }
114	
115	  function prepare(points) {
116	    let prepared = cache.get(points);
117	    if (prepared) return prepared;
118	    if (!points || points.length < 2) throw new Error('A path needs at least two points');
119	    const n = points.length, dense = [];
120	    const at = function (i) { return points[Math.max(0, Math.min(n - 1, i))]; };
121	    for (let i = 0; i < n - 1; i++) {
122	      const p0 = at(i - 1), p1 = at(i), p2 = at(i + 1), p3 = at(i + 2);
123	      for (let k = 0; k < SUB; k++) {
124	        const t = k / SUB;
125	        dense.push([
126	          catmull(p0[0], p1[0], p2[0], p3[0], t),
127	          catmull(p0[1], p1[1], p2[1], p3[1], t),
128	          p1[2] + (p2[2] - p1[2]) * t,
129	          (p1[3] || 0) + ((p2[3] || 0) - (p1[3] || 0)) * t
130	        ]);
131	      }
132	    }
133	    const last = points[n - 1];
134	    dense.push([last[0], last[1], last[2], last[3] || 0]);
135	    const cum = [0];
136	    for (let i = 1; i < dense.length; i++) {
137	      const a = dense[i - 1], b = dense[i];
138	      const len = Math.hypot(b[0] - a[0], b[1] - a[1]) / Math.max(1, (a[2] + b[2]) / 2);
139	      cum.push(cum[i - 1] + len);
140	    }
141	    const total = cum[cum.length - 1] || 1;
142	    prepared = { dense: dense, cum: cum.map(function (c) { return c / total; }), widths: total };
143	    cache.set(points, prepared);
144	    return prepared;
145	  }
146	
147	  /* Returns {x, y, w, lane, tx, ty, f}; (tx, ty) is the unit direction of travel. */
148	  function sample(points, f) {
149	    const p = prepare(points);
150	    f = f < 0 ? 0 : f > 1 ? 1 : f;
151	    const cum = p.cum, d = p.dense;
152	    let lo = 0, hi = cum.length - 1;
153	    while (hi - lo > 1) {
154	      const mid = (lo + hi) >> 1;
155	      if (cum[mid] <= f) lo = mid; else hi = mid;
156	    }
157	    const span = cum[hi] - cum[lo] || 1;
158	    const t = (f - cum[lo]) / span;
159	    const a = d[lo], b = d[hi];
160	    let tx = b[0] - a[0], ty = b[1] - a[1];
161	    const len = Math.hypot(tx, ty) || 1;
162	    return {
163	      x: a[0] + (b[0] - a[0]) * t,
164	      y: a[1] + (b[1] - a[1]) * t,
165	      w: a[2] + (b[2] - a[2]) * t,
166	      lane: a[3] + (b[3] - a[3]) * t,
167	      tx: tx / len, ty: ty / len, f: f
168	    };
169	  }
170	
171	  /* Path fraction of the point on the path closest to (x, y). */
172	  function project(points, x, y) {
173	    const p = prepare(points);
174	    let best = 0, bestD = Infinity;
175	    for (let i = 0; i < p.dense.length; i++) {
176	      const q = p.dense[i];
177	      const d = (q[0] - x) * (q[0] - x) + (q[1] - y) * (q[1] - y);
178	      if (d < bestD) { bestD = d; best = i; }
179	    }
180	    return p.cum[best];
181	  }
182	
183	  /* Foot point for a racer at fraction f, lane value laneX (-1..1, continuous)
184	     and jump height fraction jumpH (0..1). Lanes offset horizontally. */
185	  function racerPoint(points, f, laneX, jumpH) {
186	    const s = sample(points, f);
187	    return {
188	      x: s.x + (laneX || 0) * s.lane,
189	      y: s.y - (jumpH || 0) * s.w * 0.42,
190	      groundY: s.y,
191	      w: s.w, tx: s.tx, ty: s.ty, f: s.f
192	    };
193	  }
194	
195	  /* Length of the path in racer widths; useful when choosing segment lengths. */
196	  function widths(points) { return prepare(points).widths; }
197	
198	  WW.path = { prepare: prepare, sample: sample, project: project, racerPoint: racerPoint, widths: widths };
199	})(globalThis.WW = globalThis.WW || {});
200	/* Wishweave Wonders — Level 1 route (WW.LEVEL), docs/ARCHITECTURE.md §6.
201	
202	   route      Purl's connected route: the six plates alternate with "around the tower" connectors.
203	   loopRoute  Loop's own route, index-aligned with `route` (same ids, kinds and plates) but with his own lengths.
204	   stitches   the four tap interactions and the route segment that owns each one.
205	   loop       Loop's per-race variation (see below); read by sim/loop-ai.js.
206	
207	   `length` is metres; a racer at speed v advances df = v * dt / length. Every fraction (stops, pickups, reveal,
208	   finish, Loop's tasks...) lives in the plate data (WW.PLATES[plate].purl/loop.events) and is read by the sim at
209	   createRace time — nothing here repeats a plate fraction.
210	
211	   Pacing — race clock (s since GO), measured with `node tests/unit/bot.cjs --sweep=50 [--profile=first]` on the final
212	   p06/p07 data, verified by tests/unit/pacing.test.cjs (bot profiles are described in tests/unit/bot.cjs):
213	     profile                                                      Purl     Loop over seeds 1–50          Purl wins
214	     competent  taps 1.0 s after each cue, jumps 0.3 s after reveal 97.93    92.2–114.6 (mean 101.3, sd 5.1)  36/50 (72 %)
215	     first      taps 2.0 s after each cue, one hit, steers into
216	                the dropped thread 0.4 s later, same-pass recovery  102.05   (same Loop races)               19/50 (38 %)
217	   Purl's time does not depend on the seed; Loop's does (per-race form, per-segment jitter, reactions, hesitations,
218	   bypass line, hop mistakes) and never on the player. Add the 3 s countdown and the first-lesson time (the opening
219	   TOUCH → PULL → OPEN: the race clock and both racers stand still until the ribbon is open) for the wall-clock
220	   attempt length. The two profiles differ by ~4.1 s: 3 × 1 s of extra stitch reaction (the opening lesson is
221	   untimed) + ~1.1 s for the tangle/slow-down of one hit. Loop's ribbon is 10 m shorter than before the lesson
222	   became untimed, so the race balance is unchanged (he used to gain that ground while Purl opened the ribbon).
223	   Documented seeds (Loop's finish time; competent Purl 97.93 s, first-time Purl 102.05 s):
224	     competent  Purl wins: 1 (Loop 101.09), 7 (112.25), 8 (106.79)    Loop wins: 4 (92.56), 30 (94.66), 36 (92.21)
225	     first      Purl wins: 7 (112.25), 8 (106.79), 12 (105.98)        Loop wins: 2 (97.28), 4 (92.56), 5 (99.02)
226	     photo finish: seed 3, Loop 97.89 vs competent Purl 97.93
227	   Snagling dodge window (reaction measured from the reveal, 1/60 s steps): jump started 0.04–0.48 s after the
228	   reveal clears contact; a lane change started 0.00–0.41 s after it moves Purl out of the target lane in time.
229	   Lengths: every plate is ~15 m per racer width of its path (WW.path.widths), so Purl crosses each plate at a
230	   similar on-screen pace; connectors are 19 m (≈ 3.8 s turns around a tower). The landing (38 m) puts the
231	   Snagling reveal ~1.9 s after Purl enters it. Objective texts: `objective` on entry, `objectiveOpen` once the
232	   plate's stitch is open, `objectiveDone` once its thread is held, `objectiveDrop` while a thread lies dropped. */
233	(function (WW) {
234	  'use strict';
235	
236	  const route = [
237	    { id: 'ribbon', kind: 'plate', plate: 'p01', length: 128,
238	      phase: 'LEVEL 1 · START', objective: 'UNFURL THE RIBBON',
239	      objectiveOpen: 'Collect the coral thread', objectiveDone: 'FOLLOW THE RIBBON' },
240	    { id: 'c-ribbon', kind: 'connector', from: 'p01', to: 'p02', length: 19, style: 'right' },
241	    { id: 'shortcut', kind: 'plate', plate: 'p02', length: 55,
242	      phase: 'LEVEL 1 · MIDDLE', objective: 'OPEN THE SHORTCUT',
243	      objectiveOpen: 'CROSS THE SHORTCUT' },
244	    { id: 'c-shortcut', kind: 'connector', from: 'p02', to: 'p03', length: 19, style: 'right' },
245	    { id: 'tassels', kind: 'plate', plate: 'p03', length: 69,
246	      phase: 'LEVEL 1', objective: 'LIFT THE TASSELS',
247	      objectiveOpen: 'GRAB THE TEAL THREAD', objectiveDone: 'RUN TO THE LANDING' },
248	    { id: 'c-tassels', kind: 'connector', from: 'p03', to: 'p04', length: 19, style: 'right' },
249	    { id: 'landing', kind: 'plate', plate: 'p04', length: 38,
250	      phase: 'LEVEL 1', objective: 'CROSS THE LANDING',
251	      objectiveDrop: 'GET YOUR THREAD BACK' },
252	    { id: 'c-landing', kind: 'connector', from: 'p04', to: 'p06', length: 19, style: 'right' },
253	    { id: 'tapestry', kind: 'plate', plate: 'p06', length: 45,
254	      phase: 'LEVEL 1', objective: 'WAKE THE EMBROIDERY',
255	      objectiveOpen: 'GRAB THE GOLDEN THREAD', objectiveDone: 'RACE TO THE FLOWER GATE' },
256	    { id: 'c-tapestry', kind: 'connector', from: 'p06', to: 'p07', length: 19, style: 'right' },
257	    { id: 'finish', kind: 'plate', plate: 'p07', length: 27,
258	      phase: 'LEVEL 1', objective: 'REACH THE FLOWER GATE', objectiveDone: 'LEVEL 1 COMPLETE' }
259	  ];
260	
261	  /* Loop's lengths: his visible routes are the neighbouring teal ribbons/bypasses of each plate. */
262	  const loopLengths = {
263	    'ribbon': 121, 'c-ribbon': 19, 'shortcut': 49, 'c-shortcut': 19, 'tassels': 69, 'c-tassels': 19,
264	    'landing': 38, 'c-landing': 19, 'tapestry': 45, 'c-tapestry': 19, 'finish': 30
265	  };
266	
267	  const loopRoute = route.map(function (seg) {
268	    const out = { id: seg.id, kind: seg.kind, length: loopLengths[seg.id] };
269	    if (seg.kind === 'plate') out.plate = seg.plate;
270	    else { out.from = seg.from; out.to = seg.to; out.style = seg.style; }
271	    return out;
272	  });
273	
274	  WW.LEVEL = {
275	    id: 'level1',
276	    route: route,
277	    loopRoute: loopRoute,
278	    stitches: {
279	      ribbon: { seg: 'ribbon', kind: 'ribbon', interaction: 'pull', tutorial: true },  // TOUCH → PULL → OPEN (kit/pull-stitch)
280	      shortcut: { seg: 'shortcut', kind: 'shortcut' },
281	      tassels: { seg: 'tassels', kind: 'tassels' },
282	      butterfly: { seg: 'tapestry', kind: 'butterfly' }
283	    },
284	    /* Loop is a fallible computer rival. Besides the spec's per-segment speed jitter, reaction, hesitation and
285	       hop mistakes (WW.TUNING.loop*), his pace varies from race to race ("form": a whole-race multiplier on
286	       loopSpeed, independent of the player) and the line he takes over a bypass varies (± fraction of the plate's
287	       `extra` seconds). Both are symmetric — he is never slowed to guarantee a Purl win. A WW.TUNING value with
288	       the same name (loopForm, loopBypassJitter, loopDropAheadF) overrides these if it is ever added there. */
289	    loop: {
290	      form: [0.89, 1.11],
291	      bypassJitter: 0.4,
292	      dropAheadF: 0.05
293	    },
294	    /* Measured pacing and documented seeds (see the header); tests/unit/pacing.test.cjs checks them. */
295	    pacing: {
296	      competent: { purl: 97.93, purlWins: [1, 7, 8], loopWins: [4, 30, 36] },
297	      first: { purl: 102.05, purlWins: [7, 8, 12], loopWins: [2, 4, 5] }
298	    },
299	    completeObjective: 'LEVEL 1 COMPLETE',
300	    missingMessage: 'A THREAD IS MISSING'
301	  };
302	})(globalThis.WW = globalThis.WW || {});

  1	/* Wishweave Wonders — simulation: the race (docs/ARCHITECTURE.md §7, §12).
  2	
  3	   const race = WW.sim.createRace({ seed, level: WW.LEVEL, plates: WW.PLATES, tuning: WW.TUNING });
  4	   race.state / race.step(dt) / race.input(ev) / race.start() / race.pause(reason) / race.resume() / race.debug
  5	
  6	   Pure logic: no DOM, no wall clock, no Math.random. Deterministic for a seed + input sequence. Every route
  7	   fraction is read from the plate events here, at createRace time. Loop's random choices come from their own
  8	   stream (sim/loop-ai.js), so his race does not depend on what the player does.
  9	
 10	   Extra state fields beyond §7.1/§12 (all read-only for the renderer/UI):
 11	     purl.progress / loop.progress   0..1 along the racer's route to the finish trigger (race-progress thread)
 12	     purl.waitingFor                 stitch id while Purl stands at its stop, else null
 13	     purl.slowUntil, purl.jumpBuffered, loop.lane (always 0), loop.jumpT, loop.airborne, loop.form
 14	     transition.fromSeg/toSeg/fromPlate/toPlate/dur (for every kind; connector `from`/`to` are plate ids as in
 15	                                     WW.LEVEL, loop/return `from`/`to` are segment ids per §12.3)
 16	     items[id].segIndex/size/homeSeg/homeF, stitches[id].elapsed/openedAt/phaseT/seg/f/readyF,
 17	     loopTasks[key] = { key, kind, seg, segIndex, f, x, y, state: 'pending'|'react'|'hesitate'|'active'|'done', t }
 18	   `purl.airborne` is true for the whole jump; contact rules use jumpH.
 19	
 20	   TUTORIAL HOLD (the first lesson, kit/pull-stitch): while Purl waits at a stop whose stitch has `tutorial: true`
 21	   (the opening ribbon pull) and it is not yet passable, `state.tutorial = {id, stage}` with stage
 22	   'touch' | 'pull' | 'unfurl' | 'settle'. During the hold the race clock does not advance and neither racer's
 23	   route progress, tasks or timers move (Loop keeps his exact position and speed; the renderer shows both idle).
 24	   Only the stitch itself (gesture, unfurl, settle) advances. When the route is ready the hold ends and both
 25	   racers continue from where they were. Outside the hold nothing changes: Loop stays fully autonomous. */
 26	(function (WW) {
 27	  'use strict';
 28	  const sim = WW.sim = WW.sim || {};
 29	  const U = WW.util;
 30	
 31	  /* Sim-only tuning defaults for values that are not in WW.TUNING (WW.TUNING / createRace({tuning}) override). */
 32	  const DEFAULTS = {
 33	    laneMinSpacing: 20,          // §12.4: lane spacing (plate px) below which the path is single file
 34	    connectorLaneSpacing: 100,   // connectors are broad carpet turns: lanes stay available there
 35	    messageTime: 1.8,            // s a HUD message ("SNAGGED!", "THREAD RECOVERED", ...) stays up
 36	    hintTime: 4.5,               // s a plate `hint` stays up
 37	    gateOpenTime: 1.2,           // s for the flower gate to open once Purl arrives complete
 38	    returnTime: 3.0,             // s of the gate-fallback `return` transition
 39	    loopRecoverMin: 0.3,         // s Loop at least spends picking his dropped thread back up
 40	    loopAccel: null              // m/s²; null = purlAccel
 41	  };
 42	
 43	  /* ---------- route tables ---------- */
 44	
 45	  function parseRoute(level, plates, which) {
 46	    const defs = which === 'purl' ? level.route : level.loopRoute;
 47	    if (!Array.isArray(defs) || !defs.length) throw new Error('WW.sim: level ' + which + ' route is empty');
 48	    let cum = 0;
 49	    return defs.map(function (d, i) {
 50	      const s = { index: i, id: d.id, kind: d.kind, length: d.length, plate: d.plate || null, from: d.from || null,
 51	                  to: d.to || null, style: d.style || null, def: d, path: null, startF: 0, exit: 1, finish: null,
 52	                  reveal: null, loopReturn: null, stops: [], pickups: [], tasks: [], hints: [], cum: 0 };
 53	      if (!(d.length > 0)) throw new Error('WW.sim: segment ' + d.id + ' needs a positive length');
 54	      if (d.kind === 'plate') {
 55	        const plate = plates[d.plate];
 56	        if (!plate || !plate[which]) throw new Error('WW.sim: plate ' + d.plate + ' has no ' + which + ' route');
 57	        s.path = plate[which].path;
 58	        const counts = {};
 59	        (plate[which].events || []).slice().sort(function (a, b) { return a.f - b.f; }).forEach(function (ev) {
 60	          switch (ev.type) {
 61	            case 'start': s.startF = ev.f; break;
 62	            case 'stop': s.stops.push({ stitch: ev.stitch, f: ev.f, readyF: ev.readyF == null ? 0 : ev.readyF }); break;
 63	            case 'pickup': s.pickups.push({ item: ev.item, f: ev.f, lane: ev.lane || 0, size: ev.size }); break;
 64	            case 'reveal': s.reveal = ev.f; break;
 65	            case 'loopReturn': s.loopReturn = ev.f; break;
 66	            case 'exit': s.exit = ev.f; break;
 67	            case 'finish': s.finish = ev.f; break;
 68	            case 'hint': s.hints.push({ f: ev.f, text: ev.text }); break;
 69	            case 'task': {
 70	              const n = counts[ev.kind] = (counts[ev.kind] || 0) + 1;
 71	              s.tasks.push({ key: d.id + ':' + ev.kind + (n > 1 ? n : ''), kind: ev.kind, f: ev.f, x: ev.x, y: ev.y,
 72	                             dur: ev.dur == null ? null : ev.dur, extra: ev.extra || 0 });
 73	              break;
 74	            }
 75	            default: break;
 76	          }
 77	        });
 78	      } else if (d.kind !== 'connector') {
 79	        throw new Error('WW.sim: segment ' + d.id + ' has unknown kind ' + d.kind);
 80	      }
 81	      s.cum = cum;
 82	      cum += (s.exit - (i === 0 ? s.startF : 0)) * s.length;
 83	      return s;
 84	    });
 85	  }
 86	
 87	  /* Metres from (seg, f) to the first block (blockIn(seg, f) → f or null), the end of the route, or Infinity
 88	     beyond `look` metres. */
 89	  function blockDistance(R, seg, f, blockIn, look) {
 90	    let d = 0;
 91	    for (;;) {
 92	      const s = R[seg];
